// ================================================================
// ДВИЖОК: Прогностика по периодам и месяцам
// ================================================================

const MONTH_NAMES_RU = ["Январь","Февраль","Март","Апрель","Май","Июнь","Июль","Август","Сентябрь","Октябрь","Ноябрь","Декабрь"];

function reduceTo9(n) {
  if (n <= 0) return 0;
  return ((n - 1) % 9) + 1;
}

function digitsSum(str) {
  return String(str).split("").reduce((a, c) => a + Number(c), 0);
}

// Персональный год: сумма всех цифр (день рождения + месяц рождения + интересующий год), свёрнутая к 1-9
function getPersonalYear(birthDay, birthMonth, targetYear) {
  const dd = String(birthDay).padStart(2, "0");
  const mm = String(birthMonth).padStart(2, "0");
  const yyyy = String(targetYear);
  const sum = digitsSum(dd) + digitsSum(mm) + digitsSum(yyyy);
  return { raw: sum, year: reduceTo9(sum) };
}

// Аркан событий: та же сумма, свёрнутая к диапазону 1-22 (по формуле файла — однократное вычитание 22)
function getArcanaNumber(birthDay, birthMonth, targetYear) {
  const dd = String(birthDay).padStart(2, "0");
  const mm = String(birthMonth).padStart(2, "0");
  const yyyy = String(targetYear);
  let sum = digitsSum(dd) + digitsSum(mm) + digitsSum(yyyy);
  while (sum > 22) sum -= 22;
  return sum;
}

// Персональное число месяца: личный год + номер месяца (1-12), свёрнутое к 1-9
function getPersonalMonth(personalYear, monthNumber1to12) {
  return reduceTo9(personalYear + monthNumber1to12);
}

// Периоды: 7 планетарных периодов от дня рождения текущего года (52 дня первый, по 51 день остальные)
function getPeriods(birthDay, birthMonth, targetYear) {
  const lengths = [52, 51, 51, 51, 51, 51, 51];
  const start0 = Date.UTC(targetYear, birthMonth - 1, birthDay);
  const rows = [];
  let cursor = start0;
  for (let i = 0; i < 7; i++) {
    const startDate = new Date(cursor);
    const endMs = cursor + lengths[i] * 86400000;
    const endDate = new Date(endMs);
    const fmt = (d) => String(d.getUTCDate()).padStart(2, "0") + "." + String(d.getUTCMonth() + 1).padStart(2, "0") + "." + d.getUTCFullYear();
    rows.push({
      name: PERIODS_DATA[i].name,
      text: PERIODS_DATA[i].text,
      from: fmt(startDate),
      to: fmt(endDate),
    });
    cursor = endMs + 86400000;
  }
  return rows;
}

function getFullResult(day, month, year, name, targetYear) {
  const py = getPersonalYear(day, month, targetYear);
  const arcanaNum = getArcanaNumber(day, month, targetYear);

  const months = MONTH_NAMES_RU.map(function (monthName, i) {
    const pm = getPersonalMonth(py.year, i + 1);
    return {
      month: monthName,
      number: pm,
      text: MONTH_MAIN_TEXTS[pm],
      doText: MONTH_DO_TEXTS[pm],
      dontText: MONTH_DONT_TEXTS[pm],
    };
  });

  return {
    personalYear: py.year,
    personalYearText: PERSONAL_YEAR_TEXTS[py.year],
    arcanaNumber: arcanaNum,
    arcanaText: ARCANA_TEXTS[arcanaNum],
    spheres: {
      finance: FINANCE_TEXTS[py.year],
      profession: PROFESSION_TEXTS[py.year],
      personalLife: PERSONAL_LIFE_TEXTS[py.year],
      health: HEALTH_TEXTS[py.year],
    },
    periods: getPeriods(day, month, targetYear),
    months: months,
  };
}

window.PrognostikaEngine = { getFullResult, getPersonalYear, getArcanaNumber, getPersonalMonth, getPeriods };
